import { useEffect, useRef, useState } from 'react';
import { Button } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface NavItem {
  key: NavKey;
  label: string;
  danger?: boolean;
}

const NAV_ITEMS: NavItem[] = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

interface NavigationDrawerProps {
  onNavigate: (key: NavKey) => void;
}

export default function NavigationDrawer({ onNavigate }: NavigationDrawerProps) {
  const [isOpen, setIsOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setIsOpen(false);
        triggerRef.current?.focus();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen]);

  const handleSelect = (key: NavKey) => {
    onNavigate(key);
    setIsOpen(false);
    triggerRef.current?.focus();
  };

  return (
    <>
      <Button ref={triggerRef} className="jx-button" onClick={() => setIsOpen(true)}>
        Меню
      </Button>

      {isOpen ? (
        <div className="jx-drawer jx-drawer--left jx-drawer--open">
          <div
            className="jx-drawer__overlay"
            onClick={() => setIsOpen(false)}
            aria-hidden="true"
          />
          <nav
            className="jx-drawer__panel"
            role="dialog"
            aria-modal="true"
            aria-label="Навигация"
          >
            <div className="jx-drawer__header">
              <span className="jx-drawer__title">Навигация</span>
              <Button
                className="jx-button jx-button--icon jx-button--ghost"
                aria-label="Закрыть меню"
                onClick={() => setIsOpen(false)}
              >
                ✕
              </Button>
            </div>

            <ul className="jx-nav-list">
              {NAV_ITEMS.map((item) => (
                <li key={item.key} className="jx-nav-list__item">
                  <button
                    type="button"
                    className="jx-nav-item"
                    onClick={() => handleSelect(item.key)}
                  >
                    {item.label}
                  </button>
                </li>
              ))}

              <li className="jx-divider" role="separator" />

              <li className="jx-nav-list__item">
                <button
                  type="button"
                  className="jx-nav-item jx-nav-item--danger"
                  onClick={() => handleSelect('logout')}
                >
                  Выйти
                </button>
              </li>
            </ul>
          </nav>
        </div>
      ) : null}
    </>
  );
}

